update sys_dept set ancestors =

    when #{item.deptId} then #{item.ancestors}

where dept_id in

    #{item.deptId}

mapper.select:
select d.dept_id, d.parent_id, d.dept_name, d.dept_type, d.order_num, d.leader, d.remark, d.status, d.ancestors, d.phone, count(u.user_id) as user_count from sys_dept d left join sys_user u on u.dept_id = d.dept_id
and d.dept_name like concat('%', #{deptName}, '%')
and d.status = #{status}
and d.del_flag = '0'
group by d.dept_id, d.parent_id, d.ancestors, d.dept_name, d.dept_type, d.order_num, d.leader, d.remark;

select *
from sys_dept
where find_in_set(#{deptId}, ancestors);
